-- GENERATED by `python3 analytics/build.py render` from the tests in analytics/dbt/models/silver/_silver.yml and analytics/dbt/tests/. Do not edit.
-- Data quality checks: the dbt tests with meta check_name, in page order. Each row is one rule; failures should be 0.
CREATE OR REPLACE TABLE dq_checks AS
SELECT 'patient ids are unique' AS check_name,
       (SELECT coalesce(sum(n_records) - count(*), 0) FROM (
        select
            patient_id as unique_field,
            count(*) as n_records
        
        from silver_patient
        where patient_id is not null
        group by patient_id
        having count(*) > 1
       ) t) AS failures
UNION ALL
SELECT 'every patient has a known source' AS check_name,
       (SELECT coalesce(sum(n_records), 0) FROM (
        with all_values as (
        
            select
                source as value_field,
                count(*) as n_records
        
            from silver_patient
            group by source
        
        )
        
        select *
        from all_values
        where value_field not in (
            'mimic','synthea','hl7v2'
        )
       ) t) AS failures
UNION ALL
SELECT 'encounters point to a known patient' AS check_name,
       (SELECT count(*) FROM (
        with child as (
            select patient_id as from_field
            from silver_encounter
            where patient_id is not null
        ),
        
        parent as (
            select patient_id as to_field
            from silver_patient
        )
        
        select
            from_field
        
        from child
        left join parent
            on child.from_field = parent.to_field
        
        where parent.to_field is null
       ) t) AS failures
UNION ALL
SELECT 'conditions point to a known patient' AS check_name,
       (SELECT count(*) FROM (
        with child as (
            select patient_id as from_field
            from silver_condition
            where patient_id is not null
        ),
        
        parent as (
            select patient_id as to_field
            from silver_patient
        )
        
        select
            from_field
        
        from child
        left join parent
            on child.from_field = parent.to_field
        
        where parent.to_field is null
       ) t) AS failures
UNION ALL
SELECT 'observations point to a known patient' AS check_name,
       (SELECT count(*) FROM (
        with child as (
            select patient_id as from_field
            from silver_observation
            where patient_id is not null
        ),
        
        parent as (
            select patient_id as to_field
            from silver_patient
        )
        
        select
            from_field
        
        from child
        left join parent
            on child.from_field = parent.to_field
        
        where parent.to_field is null
       ) t) AS failures
UNION ALL
SELECT 'encounters do not end before they start' AS check_name,
       (SELECT count(*) FROM (
        -- Data quality: a visit never ends before it starts.
        
        SELECT encounter_id, start_at, end_at
        FROM silver_encounter
        WHERE end_at < start_at
       ) t) AS failures
UNION ALL
SELECT 'bronze has no duplicate copies left in silver' AS check_name,
       (SELECT count(*) FROM (
        select
            observation_id as unique_field,
            count(*) as n_records
        
        from silver_observation
        where observation_id is not null
        group by observation_id
        having count(*) > 1
       ) t) AS failures;
